from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.webdriver.common.action_chains import ActionChains
from selenium.common.exceptions import JavascriptException
from taf.selenium.sc.pages.view import ViewPanel
from taf.selenium.sc.pages.navigatable_page import NavigatablePage
from taf.selenium.sc.pages.configuration_management.configuration_menu import ConfigurationMenu


class ViewConfigurationPage(NavigatablePage):
    _TARGET_TAB_XPATH = '//*[@id="commissioning-header"]//span[contains(text(), "View configuration")]'
    _MENU_ROUTE_LIST = ["commissioning", "View", _TARGET_TAB_XPATH]

    def __init__(self, driver):
        super(ViewConfigurationPage, self).__init__(driver, ConfigurationMenu)
        self._managed_object_panel = ManagedObjectsPanel(driver)
        self._view_configuration_panel = ViewConfigurationPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def get_parameter(self, dist_name, abbreviation, timeout=60):
        self._managed_object_panel.go_to_target_object(dist_name, timeout)
        return self._view_configuration_panel.get_parameter(abbreviation, timeout)


class ManagedObjectsPanel(ViewPanel):
    _COLLAPSE_ALL = '//button[@*="Collapse all"]'
    _OBJECT_ICON = '//*[text()="{0}"]/ancestor::div[contains(@id, "{0}")]//mat-icon'
    _TARGET_OBJECT = '//*[text()="{}"]'
    _RIGHT = 'Right'
    _MAT_ICON_ATTR = 'data-mat-icon-name'

    def __init__(self, driver):
        super(ManagedObjectsPanel, self).__init__(driver)

    def collapse_all_objects(func):
        def wrapped(self, *args, **kwargs):
            elem = self.wait_for_enable((By.XPATH, self._COLLAPSE_ALL))
            ActionChains(self._driver).move_to_element(elem).click(elem).perform()
            return func(self, *args, **kwargs)

        return wrapped

    @collapse_all_objects
    def go_to_target_object(self, dist_name, timeout):
        object_name_list = dist_name.split('/')
        for index, object_name in enumerate(object_name_list[:-1]):
            object_xpath = self._OBJECT_ICON.format(object_name)

            elem = self.wait_for_enable((By.XPATH, object_xpath), timeout)
            self.driver.execute_script("arguments[0].scrollIntoView();", elem)

            if self._RIGHT in self.get_attribute_by_xpath(object_xpath, self._MAT_ICON_ATTR):
                self.click_enabled_element((By.XPATH, object_xpath), timeout)
        else:
            self.click_enabled_element((By.XPATH, self._TARGET_OBJECT.format(object_name_list[-1])))


class ViewConfigurationPanel(ViewPanel):
    _EDIT_BASE_XPATH = '//*[@id="{}"]'
    _MOUSE_DOWN_SCRIPT = 'document.getElementById("{}").dispatchEvent(new Event("mousedown"))'
    _INPUT_VALUE_SELECTOR = '#{} input'
    _TEXTAREA_VALUE_SELECTOR = '#{} textarea'
    _SELECT_VALUE_SELECTOR = '#{} .mat-select-min-line'
    _EDIT_SELECT = _EDIT_BASE_XPATH + '//mat-select'

    def __init__(self, driver):
        super(ViewConfigurationPanel, self).__init__(driver)

    def get_parameter(self, abbreviation, timeout):
        self.wait_for_visibility_by_xpath(self._EDIT_BASE_XPATH.format(abbreviation), timeout)
        elem = self.wait_for_enable((By.XPATH, self._EDIT_BASE_XPATH.format(abbreviation)), timeout)
        self.driver.execute_script("arguments[0].scrollIntoView();", elem)
        self.driver.execute_script(self._MOUSE_DOWN_SCRIPT.format(abbreviation))

        if self.element_exists((By.XPATH, self._EDIT_SELECT.format(abbreviation))):
            query_js = 'return document.querySelector("{}").innerText'
            query_value = query_js.format(self._SELECT_VALUE_SELECTOR.format(abbreviation))
            return self.driver.execute_script(query_value)

        query_js = 'return document.querySelector("{}").value'
        try:
            query_value = query_js.format(self._INPUT_VALUE_SELECTOR.format(abbreviation))
            return self.driver.execute_script(query_value)
        except JavascriptException:
            query_value = query_js.format(self._TEXTAREA_VALUE_SELECTOR.format(abbreviation))
            return self.driver.execute_script(query_value)
